import math

def interp(p,s):
    p=sorted(p)
    if s<=p[0][0]: return p[0][1]
    for a,b in zip(p,p[1:]):
        if a[0]<=s<=b[0]:
            f=(s-a[0])/max(.001,b[0]-a[0])
            return a[1]+f*(b[1]-a[1])
    return p[-1][1]

def control(obs):
    h=obs['hitch_deg']
    hr=math.radians(h)
    camera=obs['views'].get('camera')
    desired=0
    def convert(p):
        b,d=p
        b=math.radians(b)
        x,y=d*math.cos(b),d*math.sin(b)
        return (-math.cos(hr)*x+math.sin(hr)*y,math.sin(hr)*x+math.cos(hr)*y)
    if camera:
        left=[];right=[]
        for p in camera.get('walls',[]):
            s,l=convert(p)
            if .5<s<7: (left if l>0 else right).append((s,l))
        look=3.5
        middle=0
        if left and right:
            look=min(look,max(p[0] for p in left),max(p[0] for p in right))
            middle=(interp(left,look)+interp(right,look))/2
        corners=[convert(p) for p in camera.get('target_corners',[])]
        pairs=[]
        for i,a in enumerate(corners):
            for b in corners[i+1:]:
                ds=b[0]-a[0];dl=b[1]-a[1]
                if abs(dl)>2 and abs(ds)<1.8:
                    pairs.append((abs(ds)/abs(dl),a,b))
        if pairs:
            _,a,b=min(pairs)
            slope=-(b[0]-a[0])/(b[1]-a[1])
            center_s=(a[0]+b[0])/2
            center_l=(a[1]+b[1])/2
            look=3.5
            middle=center_l+slope*(look-center_s)
        desired=math.degrees(math.atan2(5.2*middle,look*look+middle*middle))
        desired=max(-27,min(27,desired))
    return max(-34,min(34,2.1*h-1.35*desired)),-.5,-23

