filt=32.0
def control(obs):
    global filt
    h=obs['hitch_deg']
    views=obs.get('views',{})
    cam=views.get('camera')
    if cam:
        sides=[[],[]]
        for b,d in cam.get('walls',[]):
            a=math.radians(b+h)
            x=-d*math.cos(a); y=d*math.sin(a)
            if 4<x<12 and abs(y)>0.5:
                sides[0 if y>0 else 1].append((x,y))
        if all(sides):
            vals=[]
            for pts in sides:
                pts.sort(key=lambda p:abs(p[0]-8))
                pts=pts[:3]
                vals.append(sum(p[1] for p in pts)/len(pts))
            desired=max(-32,min(32,math.degrees(math.atan2(20.4*(vals[0]+vals[1])/2,64))))
            filt+=0.08*(desired-filt)
    steer=max(-30,min(30,1.55*h-1.18*filt))
    direct=views.get('direct')
    if direct:
        ox,oy=direct['origin']
        clear=10
        for b,d in direct.get('walls',[]):
            a=math.radians(b)
            x=ox+d*math.cos(a); y=oy+d*math.sin(a)
            if 2.5<x<6.8 and y<0:
                clear=min(clear,-y-1.275)
        steer=min(steer,max(-8,20*(clear-0.3)))
    if abs(h)>48:
        wake('Hitch angle needs attention')
        return (steer,0,-41)
    return (steer,-0.35,-41)

